class Solution:
    def wordSquaresII(self, words: List[str]) -> List[List[str]]:
        n = len(words)
        res = []
        for a in range(n):
            for b in range(n):
                for c in range(n):
                    for d in range(n):
                        if len({a, b, c, d}) < 4: continue
                        if (words[a][0] == words[b][0] and words[a][3] == words[c][0]
                                and words[d][0] == words[b][3] and words[d][3] == words[c][3]):
                            res.append([words[a], words[b], words[c], words[d]])
        res.sort()
        return res

