class Solution {
public:
    vector<vector<string>> wordSquaresII(vector<string>& words) {
        int n = words.size();
        vector<vector<string>> res;
        for (int a = 0; a < n; a++)
            for (int b = 0; b < n; b++)
                for (int c = 0; c < n; c++)
                    for (int d = 0; d < n; d++) {
                        if (a == b || a == c || a == d || b == c || b == d || c == d) continue;
                        if (words[a][0] == words[b][0] && words[a][3] == words[c][0]
                            && words[d][0] == words[b][3] && words[d][3] == words[c][3])
                            res.push_back({words[a], words[b], words[c], words[d]});
                    }
        sort(res.begin(), res.end());
        return res;
    }
};

