class Solution {
    public List<List<String>> wordSquaresII(String[] words) {
        int n = words.length;
        List<List<String>> res = new ArrayList<>();
        for (int a = 0; a < n; a++)
            for (int b = 0; b < n; b++)
                for (int c = 0; c < n; c++)
                    for (int d = 0; d < n; d++) {
                        if (a == b || a == c || a == d || b == c || b == d || c == d) continue;
                        if (words[a].charAt(0) == words[b].charAt(0)
                            && words[a].charAt(3) == words[c].charAt(0)
                            && words[d].charAt(0) == words[b].charAt(3)
                            && words[d].charAt(3) == words[c].charAt(3))
                            res.add(Arrays.asList(words[a], words[b], words[c], words[d]));
                    }
        res.sort(Comparator.comparing(x -> x.toString()));
        return res;
    }
}

