var wordSquaresII = function(words) {
    const n = words.length, res = [];
    for (let a = 0; a < n; a++)
        for (let b = 0; b < n; b++)
            for (let c = 0; c < n; c++)
                for (let d = 0; d < n; d++) {
                    if (new Set([a, b, c, d]).size < 4) continue;
                    if (words[a][0] === words[b][0] && words[a][3] === words[c][0]
                        && words[d][0] === words[b][3] && words[d][3] === words[c][3])
                        res.push([words[a], words[b], words[c], words[d]]);
                }
    return res.sort((x, y) => x.join('|').localeCompare(y.join('|'), undefined, {numeric: false})
        || (x.join('|') < y.join('|') ? -1 : x.join('|') > y.join('|') ? 1 : 0));
};
